[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$ReceiptPath,[string]$BudgetPath='', [string]$ExpectedStagingUrl='', [string]$ExpectedDeploymentId='')
$ErrorActionPreference='Stop';$issues=[Collections.Generic.List[string]]::new();$r=Get-Content -Raw -Encoding UTF8 -LiteralPath $ReceiptPath|ConvertFrom-Json
if($r.schemaVersion -ne 1){$issues.Add('SCHEMA_VERSION')};if($r.recordType -ne 'WebPageStudioReleaseAcceptanceReceipt'){$issues.Add('RECORD_TYPE')};foreach($n in 'receiptId','status','staging','budgets','metrics','artifact','rollback','cacheUpdate','runtimeStatus','nonClaims'){if($null -eq $r.PSObject.Properties[$n]){$issues.Add("MISSING_$n")}}
if($r.staging.https -ne $true -or [string]$r.staging.url -notmatch '^https://'){$issues.Add('STAGING_HTTPS_REQUIRED')};if($r.metrics.p75 -ne $true){$issues.Add('P75_REQUIRED')};if([string]$r.artifact.artifactHash -notmatch '^[a-f0-9]{64}$'){$issues.Add('ARTIFACT_HASH_INVALID')};if($r.status -eq 'accepted' -and -not $r.rollback.tested){$issues.Add('ROLLBACK_NOT_TESTED')};if($r.status -eq 'not-run' -and $r.runtimeStatus -ne 'runtime-not-run'){$issues.Add('NOT_RUN_STATUS')};if($r.status -eq 'accepted' -and ($r.metrics.lcpMs -gt $r.budgets.lcpMs -or $r.metrics.inpMs -gt $r.budgets.inpMs -or $r.metrics.cls -gt $r.budgets.cls)){$issues.Add('BUDGET_EXCEEDED')};if($r.cacheUpdate.strategy -notin @('immutable-hash','purge-and-revalidate','service-worker-versioned')){$issues.Add('CACHE_STRATEGY_INVALID')};if($r.status -eq 'accepted' -and (-not $r.cacheUpdate.purgeObserved -or [string]::IsNullOrWhiteSpace([string]$r.cacheUpdate.versionKey))){$issues.Add('CACHE_UPDATE_NOT_OBSERVED')}
if($BudgetPath -and $r.budgets.PSObject.Properties['budgetConfigHash']){$actual=(Get-FileHash -LiteralPath $BudgetPath -Algorithm SHA256).Hash.ToLowerInvariant();if([string]$r.budgets.budgetConfigHash -cne $actual){$issues.Add('BUDGET_CONFIG_HASH_DRIFT')}}
if($ExpectedStagingUrl -and [string]$r.staging.url -cne $ExpectedStagingUrl){$issues.Add('STAGING_URL_DRIFT')};if($ExpectedDeploymentId -and [string]$r.staging.deploymentId -cne $ExpectedDeploymentId){$issues.Add('DEPLOYMENT_ID_DRIFT')}
$o=[ordered]@{validator='release-acceptance-receipt';status=if($issues.Count){'blocked'}else{'passed'};findingCount=$issues.Count;findings=@($issues);runtimeStatus=[string]$r.runtimeStatus;nonClaims=@('staging-does-not-prove-production-capacity','budget-pass-does-not-prove-business-readiness')};$o|ConvertTo-Json -Depth 8;if($issues.Count){exit 1}
